// Real token validation for feedback (Phase 2B fix)
// Token from env credential, exact match only, reject missing/wrong, never log
const headers = $input.first().json.headers || $json.headers || {};
const body = $input.first().json.body || $json.body || $json;

const expected = ($env.N8N_WEBHOOK_TOKEN || $env.N8N_CALLBACK_TOKEN || '').trim();
if (!expected) {
  throw new Error('Server misconfigured: shared token not set in n8n env');
}
const authHeader = (headers['authorization'] || '').trim();
const bearer = authHeader.toLowerCase().startsWith('bearer ') ? authHeader.slice(7).trim() : '';
const supplied = (headers['x-n8n-token'] || headers['x-callback-token'] || bearer || '').trim();
if (!supplied) {
  throw new Error('Missing authentication token - X-N8N-Token required');
}
if (supplied !== expected) {
  throw new Error('Invalid authentication token');
}

// Validate verdict allow-list (no autonomous)
const allowed = ['true_positive','false_positive','benign','escalate','acknowledged','resolved','contain_requested'];
const verdict = (body.verdict || body.payload && body.payload.verdict || '').toLowerCase();
if (verdict && !allowed.includes(verdict)) {
  throw new Error(`Invalid verdict: ${verdict} not in allow-list`);
}

// Ensure no full_log
const payloadStr = JSON.stringify(body).toLowerCase();
if (payloadStr.includes('full_log')) {
  throw new Error('Security violation: payload must not contain full_log');
}

// Clarify contain_requested behavior
if (verdict === 'contain_requested') {
  console.log('contain_requested creates an approval-required request; no containment action is executed');
}

return { json: body.payload ? body.payload : body };
